from .packet_extractor import PacketExtractor
from .capture_condition_tracker import CaptureConditionTracker
from .command_executor import CommandExecutor
from .capture_command import CaptureCommand
from .timer import Timer
from .logger import Logger
from contextlib import closing
from taf.ul.ettf.utils.exception import LibraryError
from taf.ul.ettf.utils import exception_causes


LESS_1200B = 'less 1200'


class TypeToConvertError(LibraryError):
    def __init__(self, msg):
        super(TypeToConvertError, self).__init__(exception_causes.INVALID_INPUT, msg)


def create_logger(interfaces, pdml_parser, msg_filter=None, capture_filter=LESS_1200B):
    condition_tracker = CaptureConditionTracker(Timer(), PacketExtractor(pdml_parser))
    capture_cmd = CaptureCommand(interfaces, msg_filter, capture_filter).value
    cmd_executor = CommandExecutor(capture_cmd)

    return Logger(cmd_executor, condition_tracker)


def scoped_logger(interface, pdml_parser, msg_filter=None, capture_filter=None):
    return closing(create_logger(interface, pdml_parser, msg_filter, capture_filter))


def assert_variable_conversion_type(var_value, expected_type, var_name):
    try:
        expected_type(var_value)
    except ValueError:
        raise TypeToConvertError('Variable \'{}\' is of incorrect type! Its value is: \'{}\', '
                                 'which is not of expected {}'.format(var_name, var_value, expected_type))
    return var_value
